package com.mhtextractor.util;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.i18n.I18n;
import com.mhtextractor.model.GroupItem;
import com.mhtextractor.model.ParamScope;

import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 输出单元计划构建（F5 6.4/6.8，阶段 8）：数据模型 → 输出单元列表。
 *
 * <p>单元划分：未分组项目按"来源目录 + 生效参数内容"分桶（条目独立参数需求拍板）——参数内容
 * 相同（如均继承全局）的同来源条目合并为一个输出，输出名 = 来源目录名（同源多桶时第二个起追加序号）；
 * 单独输出模式的桶直写会话目录（输出名 null）。每个组为一个独立单元（组名经
 * {@link SanitizeUtils#sanitize} 清洗后命名输出；空组跳过）。
 * 单元参数解析沿用 {@link ParamScope#effectiveParams} 三层覆盖（组 &gt; 条目 &gt; 全局；
 * 均未确认时回退默认参数实例）。单元按"首个构成条目在数据序中的位置"排序。</p>
 *
 * <p>本类不感知 GUI 状态，全部方法为纯函数，供 MainController 与单元测试共用。</p>
 */
public final class OutputUnitPlanner {

    private OutputUnitPlanner() {
    }

    /** 项目信息视图：将任意项目类型映射为规划所需字段 */
    public interface ItemView<I> {
        String path(I item);

        String sourceFolder(I item);

        boolean removed(I item);

        /**
         * 功能一：该条目本次是否参与提取（默认全部参与）。
         * 开关关闭时恒 true；打开时 = 条目被勾选（由 GUI 视图实现给出）。
         */
        default boolean checked(I item) {
            return true;
        }

        /** 条目级文本参数（null = 未设置；条目独立参数需求） */
        AppConfig textItemParams(I item);

        /** 条目级图片参数（null = 未设置；条目独立参数需求） */
        AppConfig imageItemParams(I item);
    }

    /**
     * 视图装饰（功能一）：返回与 {@code base} 字段相同、但 {@link ItemView#checked} 改由
     * {@code checked} 判定的视图。开关关闭时不必装饰（默认恒 true）。纯函数、零副作用。
     */
    public static <I> ItemView<I> withChecked(ItemView<I> base, java.util.function.Predicate<I> checked) {
        java.util.Objects.requireNonNull(base, "base");
        java.util.Objects.requireNonNull(checked, "checked");
        return new ItemView<>() {
            @Override public String path(I item) { return base.path(item); }

            @Override public String sourceFolder(I item) { return base.sourceFolder(item); }

            @Override public boolean removed(I item) { return base.removed(item); }

            @Override public boolean checked(I item) { return checked.test(item); }

            @Override public AppConfig textItemParams(I item) { return base.textItemParams(item); }

            @Override public AppConfig imageItemParams(I item) { return base.imageItemParams(item); }
        };
    }

    /**
     * 本次输出单元里是否存在"合并单元"（功能一提示卡判定条件③）：任意组单元，或未分组的合并桶
     * （文本模式 = 非单独输出；图片模式 = 单输出/合并）。纯函数。
     */
    public static boolean hasMergedUnit(List<OutputUnit> units, boolean imageMode) {
        for (OutputUnit u : units) {
            if (u.isGroup()) {
                return true;
            }
            AppConfig p = u.getParams();
            boolean merged = imageMode ? p.isSingleOutputMode() : !p.isSeparateFiles();
            if (merged) {
                return true;
            }
        }
        return false;
    }

    /** 输出单元：一组按数据序排列的文件 + 生效参数 + 输出路径 */
    public static final class OutputUnit {
        /** sanitize 后的输出名（合并模式的输出文件/目录名、组单独模式的子文件夹名）；未分组单独单元为 null */
        private final String outputName;
        /** 是否组单元（false = 未分组来源单元） */
        private final boolean group;
        /** 生效参数（已回退默认实例，调用方补充运行时 GUI 字段） */
        private final AppConfig params;
        /** 单元内文件路径（保持数据序） */
        private final List<String> paths;
        /** 输出路径：合并文本 = 文件路径；其余 = 目录路径 */
        private final String outputPath;

        public OutputUnit(String outputName, boolean group, AppConfig params, List<String> paths,
                   String outputPath) {
            this.outputName = outputName;
            this.group = group;
            this.params = params;
            this.paths = List.copyOf(paths);
            this.outputPath = outputPath;
        }

        public String getOutputName() {
            return outputName;
        }

        public boolean isGroup() {
            return group;
        }

        public AppConfig getParams() {
            return params;
        }

        public List<String> getPaths() {
            return paths;
        }

        public String getOutputPath() {
            return outputPath;
        }

        public int fileCount() {
            return paths.size();
        }

        /** 日志/展示用单元名：未分组单独单元显示"未分组" */
        public String label() {
            return outputName != null ? outputName : I18n.get("core.ungrouped");
        }
    }

    /**
     * 构建输出单元计划。
     *
     * @param dataOrder    数据序列表（I 与 GroupItem&lt;I&gt; 混合）
     * @param view         项目字段视图
     * @param imageMode    当前提取模式（文本/图片）
     * @param textGlobal   全局文本参数（null = 未确认）
     * @param imageGlobal  全局图片参数（null = 未确认）
     * @param sessionDir   会话输出目录
     */
    public static <I> List<OutputUnit> plan(List<?> dataOrder, ItemView<I> view,
                                            boolean imageMode, AppConfig textGlobal,
                                            AppConfig imageGlobal, String sessionDir) {
        List<UnitEntry> entries = new ArrayList<>();
        // 未分组项目按"来源+生效参数内容"分桶（条目独立参数需求拍板；LinkedHashMap 保持首次出现序）
        Map<BucketKey, List<I>> ungroupedByKey = new LinkedHashMap<>();
        Map<BucketKey, Integer> keyFirstPos = new HashMap<>();
        boolean anyUngrouped = false;
        int pos = 0;

        for (Object o : dataOrder) {
            if (o instanceof GroupItem<?> g) {
                OutputUnit groupUnit = groupUnit(g, view, imageMode, textGlobal, imageGlobal, sessionDir);
                if (groupUnit != null) {
                    entries.add(new UnitEntry(pos, groupUnit));
                }
            } else {
                @SuppressWarnings("unchecked")
                I item = (I) o;
                if (!view.removed(item) && view.checked(item)) {
                    anyUngrouped = true;
                    AppConfig itemParams = resolveItem(item, view, imageMode, textGlobal, imageGlobal);
                    boolean separate = imageMode ? !itemParams.isSingleOutputMode() : itemParams.isSeparateFiles();
                    // 单独输出桶不区分来源（直写会话目录，跨来源同参数合一单元，与改造前一致）
                    BucketKey key = new BucketKey(separate ? "" : sourceKey(view.sourceFolder(item)), itemParams);
                    keyFirstPos.putIfAbsent(key, pos);
                    ungroupedByKey.computeIfAbsent(key, k -> new ArrayList<>()).add(item);
                }
            }
            pos++;
        }

        if (anyUngrouped) {
            // 同名（同来源）合并桶计数：第二个起追加序号（小说A.txt、小说A(2).txt）
            Map<String, Integer> usedNames = new HashMap<>();
            for (Map.Entry<BucketKey, List<I>> e : ungroupedByKey.entrySet()) {
                AppConfig params = e.getKey().params();
                boolean separate = imageMode ? !params.isSingleOutputMode() : params.isSeparateFiles();
                String name;
                String outputPath;
                if (separate) {
                    // 单独输出：各单元直写会话目录（输出名 null，成员文件名互不冲突）
                    name = null;
                    outputPath = sessionDir;
                } else {
                    String base = sourceOutputName(e.getKey().source(), imageMode);
                    int n = usedNames.merge(base, 1, Integer::sum);
                    name = n == 1 ? base : base + "(" + n + ")";
                    outputPath = imageMode
                            ? new File(sessionDir, name).getPath()
                            : new File(sessionDir, name + ".txt").getPath();
                }
                entries.add(new UnitEntry(keyFirstPos.get(e.getKey()),
                        new OutputUnit(name, false, params, pathsOf(e.getValue(), view), outputPath)));
            }
        }

        entries.sort(java.util.Comparator.comparingInt(e -> e.position));
        return entries.stream().map(e -> e.unit).toList();
    }

    /** 未分组分桶键：来源目录 + 生效参数（AppConfig 按内容 equals，参数内容相同即同桶） */
    private record BucketKey(String source, AppConfig params) {
    }

    /** 单元 + 首个构成条目在数据序中的位置（用于按首次出现排序） */
    private static final class UnitEntry {
        final int position;
        final OutputUnit unit;

        UnitEntry(int position, OutputUnit unit) {
            this.position = position;
            this.unit = unit;
        }
    }

    /** 组单元：成员全部移除（空组）时返回 null */
    private static <I> OutputUnit groupUnit(GroupItem<?> g, ItemView<I> view, boolean imageMode,
                                            AppConfig textGlobal, AppConfig imageGlobal,
                                            String sessionDir) {
        List<I> members = new ArrayList<>();
        for (Object m : g.getMembers()) {
            @SuppressWarnings("unchecked")
            I item = (I) m;
            if (!view.removed(item) && view.checked(item)) {
                members.add(item);
            }
        }
        if (members.isEmpty()) {
            return null;
        }

        AppConfig params = resolve(g, null, null, imageMode, textGlobal, imageGlobal);
        boolean separate = imageMode ? !params.isSingleOutputMode() : params.isSeparateFiles();
        String name = sanitizedGroupName(g);
        String outputPath = (!imageMode && !separate)
                ? new File(sessionDir, name + ".txt").getPath()
                : new File(sessionDir, name).getPath();
        return new OutputUnit(name, true, params, pathsOf(members, view), outputPath);
    }

    private static String sanitizedGroupName(GroupItem<?> g) {
        String s = SanitizeUtils.sanitize(g.getName());
        if (s.isEmpty()) {
            return I18n.get("core.groupDefault") + g.getGroupNo();
        }
        return s;
    }

    private static String sourceOutputName(String sourceFolder, boolean imageMode) {
        String dirName = sourceFolder == null || sourceFolder.isEmpty()
                ? "" : new File(sourceFolder).getName();
        String s = SanitizeUtils.sanitize(dirName);
        if (s.isEmpty()) {
            return imageMode ? "All_Images" : "mht_output";
        }
        return s;
    }

    private static String sourceKey(String sourceFolder) {
        return sourceFolder == null ? "" : sourceFolder;
    }

    private static AppConfig resolve(GroupItem<?> parentGroup, AppConfig itemText, AppConfig itemImage,
                                     boolean imageMode, AppConfig textGlobal, AppConfig imageGlobal) {
        AppConfig p = ParamScope.effectiveParams(parentGroup, itemText, itemImage,
                imageMode, textGlobal, imageGlobal);
        return p != null ? p : new AppConfig();
    }

    /** 未分组条目的生效参数（组参数恒为 null，条目参数取 ItemView 快照） */
    private static <I> AppConfig resolveItem(I item, ItemView<I> view, boolean imageMode,
                                             AppConfig textGlobal, AppConfig imageGlobal) {
        return resolve(null, view.textItemParams(item), view.imageItemParams(item),
                imageMode, textGlobal, imageGlobal);
    }

    private static <I> List<String> pathsOf(List<I> items, ItemView<I> view) {
        List<String> out = new ArrayList<>(items.size());
        for (I it : items) {
            out.add(view.path(it));
        }
        return out;
    }
}
package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.processor.ImageBatchProcessor;
import com.mhtextractor.util.SanitizeUtils;
import com.mhtextractor.util.SourceKinds;

import java.io.File;

/**
 * 产物命名规则（P3-3b）：文本模式输出文件名 / 图片模式输出目录名的<b>名字本体</b>计算，
 * 从 {@code gui.controller.WorkspaceInfoPresenter} 原样下沉到 app 层 ——
 * 判定与回落顺序逐条照搬搬迁前的 {@code updateInfoArea} 命名段与
 * {@code separateDirName} / {@code mergedFolderName}（只搬不改）。
 *
 * <p>本类只产名字本体，<b>不产任何展示文案</b>：解析中状态经 {@link Name#parsing()} 表达
 * （此时 {@link Name#value()} 为 null），由 gui 层用 {@code preview.parsing} 键渲染；
 * 前后缀（preview.* 键）与最终显示字符串仍由 gui 层拼装。</p>
 *
 * <p>本类<b>零 JavaFX、零 I18n</b>，属 {@code app} 层。</p>
 */
public final class OutputNameService {

    private OutputNameService() {
    }

    /**
     * 文本模式输出文件名本体（不含 {@code preview.outputFilePrefix} 前缀与
     * {@code preview.outputFileTxtSuffix} 后缀）：
     * separate → {@code SourceKinds.stripKnownExtension(item.name) + ".txt"}；
     * merged → {@code <输入目录名，空则 "mht_output"> + ".txt"}。
     */
    public static String textOutputName(PreviewItem item, AppConfig params, String inputFolder) {
        if (params.isSeparateFiles()) {
            return SourceKinds.stripKnownExtension(item.name) + ".txt";
        }
        String inputDirName = new File(inputFolder).getName();
        if (inputDirName.isEmpty()) {
            inputDirName = "mht_output";
        }
        return inputDirName + ".txt";
    }

    /**
     * 图片模式输出目录名本体。singleOutput（合并）用首条可见项 {@code firstVisible} 的标题，
     * 回落 {@link ImageBatchProcessor#determineDefaultFolderName}；否则（单独）用 {@code item} 的标题，
     * 回落 {@link SourceKinds#stripKnownExtension}（与搬迁前 {@code mergedFolderName} /
     * {@code separateDirName} 逐条一致：标题提取开启且状态 WAITING → 解析中；cachedTitle 非空 → sanitize）。
     */
    public static Name imageOutputName(PreviewItem item, AppConfig params, PreviewItem firstVisible, String inputFolder) {
        if (params.isSingleOutputMode()) {
            if (params != null && params.isEnableNameExtraction() && firstVisible != null) {
                if (firstVisible.status == PreviewItem.Status.WAITING) {
                    return new Name(null, true);
                }
                if (firstVisible.cachedTitle != null) {
                    return new Name(SanitizeUtils.sanitize(firstVisible.cachedTitle), false);
                }
            }
            return new Name(ImageBatchProcessor.determineDefaultFolderName(inputFolder), false);
        }
        if (params != null && params.isEnableNameExtraction()) {
            if (item.status == PreviewItem.Status.WAITING) {
                return new Name(null, true);
            }
            if (item.cachedTitle != null) {
                return new Name(SanitizeUtils.sanitize(item.cachedTitle), false);
            }
        }
        return new Name(SourceKinds.stripKnownExtension(item.name), false);
    }

    /**
     * 图片模式输出目录名本体的计算产物：{@code parsing} = true 表示「解析中」，
     * 此时 {@code value} 为 null —— 展示文案（{@code preview.parsing}）由 gui 层渲染，
     * app 不产文案。
     */
    public record Name(String value, boolean parsing) {
    }
}
package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.processor.PerFileOverrides;
import com.mhtextractor.util.OutputUnitPlanner;
import com.mhtextractor.uiport.OutputUnitVm;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 提取运行时配置与输出单元计划（P3-3b-3，矩阵缺口 7/8）：把
 * {@code gui.ExtractionTaskCoordinator.buildRuntimeConfig} 与 {@code startExtractionTask} 里的
 * 两段<b>纯计算</b>原样搬到 app 层（只搬不改：配置字段写入顺序、单元参数补充顺序与搬迁前逐字一致）。
 *
 * <p>零 JavaFX、零 I18n；不产任何文案（{@code log.maincontroller.33} 的日志键与实参构造留在 gui 侧）。</p>
 */
public final class ExtractionPlanService {

    /** 当前已确认参数和会话状态；由宿主提供实时读取，不缓存控件值。 */
    public interface Context {
        List<Object> dataOrder();
        boolean imageMode();
        AppConfig textParamsCache();
        AppConfig imageParamsCache();
        String inputFolder();
        String outputFolder();
        boolean openFolderAfterComplete();
    }

    private final Context context;
    private String sessionOutputFolder;

    public ExtractionPlanService(Context context) {
        this.context = java.util.Objects.requireNonNull(context);
    }

    /** 正式运行前绑定已建立的会话目录；查询本身不创建目录。 */
    public void setSessionOutputFolder(String folder) {
        sessionOutputFolder = folder;
    }

    public AppConfig runtimeConfig() {
        return runtimeConfig(context.imageMode(), context.imageParamsCache(), context.textParamsCache(),
                context.inputFolder(), context.outputFolder(), context.openFolderAfterComplete());
    }

    AppConfig effectiveParams(PreviewItem item) {
        return com.mhtextractor.model.ParamScope.effectiveParams(item.parentGroup,
                item.textItemParams, item.imageItemParams, context.imageMode(),
                context.textParamsCache(), context.imageParamsCache());
    }

    AppConfig effectiveImageParams(PreviewItem item) {
        return com.mhtextractor.model.ParamScope.effectiveImageParams(item.parentGroup,
                item.imageItemParams, context.imageParamsCache());
    }

    public List<OutputUnitVm> outputUnitPlan(boolean checkedOnly) {
        return plan(context.dataOrder(), context.imageMode(), context.textParamsCache(), context.imageParamsCache(),
                sessionOutputFolder == null ? context.outputFolder() : sessionOutputFolder,
                context.inputFolder(), context.outputFolder(), context.openFolderAfterComplete(), checkedOnly)
                .stream().map(u -> new OutputUnitVm(u.getOutputName(), u.isGroup(), u.getParams(),
                        u.getPaths(), u.getOutputPath(), u.getOutputName() == null ? "core.ungrouped" : null)).toList();
    }

    /**
     * 输出单元规划字段视图的 gui 侧返回类型别名（协变返回）：让 gui 层对视图类型的引用
     * 落在 app 层（gui 直连业务包计数只减不增，不再直连 {@code util} 的视图接口）。
     */
    public interface ItemView extends OutputUnitPlanner.ItemView<PreviewItem> {
    }

    /** 原 {@code MainController.ITEM_VIEW}（阶段 8）：路径 / 来源目录 / 移除标记 / 条目级参数；checked 用默认恒 true。 */
    private static final ItemView ITEM_VIEW = new ItemView() {
        @Override
        public String path(PreviewItem item) {
            return item.path;
        }

        @Override
        public String sourceFolder(PreviewItem item) {
            return item.sourceFolder;
        }

        @Override
        public boolean removed(PreviewItem item) {
            return item.removed;
        }

        @Override
        public AppConfig textItemParams(PreviewItem item) {
            return item.textItemParams;
        }

        @Override
        public AppConfig imageItemParams(PreviewItem item) {
            return item.imageItemParams;
        }
    };

    /**
     * 字段视图（原 {@code MainController} 的 Host 实现）：功能一（只提取选中）开关打开时把
     * "参与"判定交给 checked（条目勾选）；关闭时用默认视图（checked 恒 true）。
     */
    public static ItemView itemView(boolean checkedOnly) {
        if (!checkedOnly) {
            return ITEM_VIEW;
        }
        OutputUnitPlanner.ItemView<PreviewItem> decorated = OutputUnitPlanner.withChecked(ITEM_VIEW, it -> it.selected);
        return new ItemView() {
            @Override public String path(PreviewItem item) { return decorated.path(item); }
            @Override public String sourceFolder(PreviewItem item) { return decorated.sourceFolder(item); }
            @Override public boolean removed(PreviewItem item) { return decorated.removed(item); }
            @Override public boolean checked(PreviewItem item) { return decorated.checked(item); }
            @Override public AppConfig textItemParams(PreviewItem item) { return decorated.textItemParams(item); }
            @Override public AppConfig imageItemParams(PreviewItem item) { return decorated.imageItemParams(item); }
        };
    }

    /**
     * 以已确认参数（未确认时用默认参数）+ 主窗口 GUI 状态构建运行时提取配置
     * （原 {@code ExtractionTaskCoordinator.buildRuntimeConfig}，逐条照搬）：
     * 取当前模式参数缓存，null 则新建默认实例，随后按序补四个运行时字段。
     *
     * <p><b>注意</b>：参数缓存非 null 时就地修改该实例（搬迁前语义）。</p>
     */
    public static AppConfig runtimeConfig(boolean imageMode, AppConfig imageParams, AppConfig textParams,
                                          String inputFolder, String outputFolder, boolean openFolderAfterComplete) {
        AppConfig config = imageMode ? imageParams : textParams;
        if (config == null) {
            config = new AppConfig();
        }
        config.setInputFolder(inputFolder);
        config.setOutputFolder(outputFolder);
        config.setImageModeEnabled(imageMode);
        config.setOpenFolderAfterComplete(openFolderAfterComplete);
        return config;
    }

    /**
     * 构建输出单元计划（原 {@code ExtractionTaskCoordinator.startExtractionTask} 内的计划组装，
     * 逐条照搬）：先按数据序 + 字段视图（功能一按需过滤勾选）规划单元，再对每个单元按序补
     * 运行时字段（{@code setInputFolder → setOutputFolder → setImageModeEnabled →
     * setOpenFolderAfterComplete}）。纯计算：不产文案、不触碰控件状态。
     */
    public static List<OutputUnitPlanner.OutputUnit> plan(List<Object> dataOrder, boolean imageMode,
                                                          AppConfig textParams, AppConfig imageParams,
                                                          String sessionOutputFolder, String inputFolder,
                                                          String outputFolder, boolean openFolderAfterComplete,
                                                          boolean checkedOnly) {
        List<OutputUnitPlanner.OutputUnit> units = OutputUnitPlanner.plan(
                dataOrder, itemView(checkedOnly), imageMode, textParams, imageParams, sessionOutputFolder);
        for (OutputUnitPlanner.OutputUnit unit : units) {
            AppConfig params = unit.getParams();
            params.setInputFolder(inputFolder);
            params.setOutputFolder(outputFolder);
            params.setImageModeEnabled(imageMode);
            params.setOpenFolderAfterComplete(openFolderAfterComplete);
        }
        return units;
    }

    /**
     * 构建「每文件覆盖」映射（原 {@code ExtractionTaskCoordinator.overrides}，逐条照搬）：
     * 按传入顺序放入 {@link LinkedHashMap}，键为 {@code item.path}，值为
     * {@code chapterEnabled} / {@code titleOverride} 两字段的覆盖。
     */
    public static Map<String, PerFileOverrides> overrides(List<PreviewItem> items) {
        Map<String, PerFileOverrides> map = new LinkedHashMap<>();
        for (PreviewItem item : items) {
            // 标题覆盖 = 用户在查看器「提取标题」文本框里的编辑值（null/空白 = 用提取值）
            map.put(item.path, new PerFileOverrides(item.chapterEnabled, item.titleOverride));
        }
        return map;
    }
}

package com.mhtextractor.app;

import com.mhtextractor.cache.PreviewCacheLifecycle;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.i18n.I18n;
import com.mhtextractor.processor.BatchProcessor;
import com.mhtextractor.processor.ImageBatchProcessor;
import com.mhtextractor.processor.PerFileOverrides;
import com.mhtextractor.processor.TextBatchProcessor;
import com.mhtextractor.util.OutputUnitPlanner;
import com.mhtextractor.util.UnitProgressAggregator;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

/**
 * 工作区提取服务（Q3 / P2）—— 把「点开始提取之后、结果回到界面之前」的<b>业务段</b>从 GUI 控制器
 * 搬进无头应用层。
 *
 * <p><b>搬进来的是什么</b>：逐输出单元调用 processor、跨单元进度聚合、统计累计（成功/失败/跳过/警告
 * + 三条详情 + 结构化单文件结果）、取消传播（{@code cancelled} 为真即跳出，已完成单元结果保留为
 * partial）、单元失败不中断整批、以及文本/图片的分派（{@link UnitProcessor}）。</p>
 *
 * <p><b>有意不搬的是什么</b>（属渲染层 / 宿主生命周期，留在
 * {@code com.mhtextractor.gui.controller.ExtractionTaskCoordinator}）：</p>
 * <ul>
 *   <li>JavaFX {@code Task} 的创建/启动/取消与 {@code progressProperty} 映射；</li>
 *   <li><b>递归深度超限确认卡</b>：{@code Platform.runLater} + {@code NotificationHost} 只能跑在 FX 线程，
 *       本类只接收一个 {@link Supplier}（{@link ExtractionRequest#recursionCallback()}）并在后台线程同步等待
 *       其返回值 —— 决策机制仍由 GUI 注入，等待语义与搬迁前一致；</li>
 *   <li>提取完成后打开输出目录、满格条三态配色、结果回写列表条目。</li>
 * </ul>
 *
 * <p><b>日志与 i18n 边界</b>：本类<b>只</b>用 {@code log.*} 键（业务层日志已国际化，随
 * {@code log.maincontroller.*} 逐键保持不变），<b>不新增</b>任何 {@code I18n.get} 界面文案，因此
 * {@code ArchitectureTest.businessLayerI18nUsageDoesNotGrow} 的基线（52）不受影响。
 * 唯一的 {@code I18n.get} 是单元失败详情键 {@code extract.unitFailed} —— 它在搬迁前就由提取业务段产出，
 * 是"写入统计详情的业务文案"而非界面文案，原样保留。</p>
 *
 * <p><b>本类零 JavaFX</b>，由 {@code ArchitectureTest.businessPackagesHaveNoUiFrameworkDependency}
 * 按字节码常量池强制。</p>
 */
@Slf4j
public final class WorkspaceExtractionService {

    /** 端口快照转为既有执行请求；不重新规划，确保执行的就是前端查询所得的计划。 */
    public static ExtractionRequest fromPlan(String sessionOutputFolder,
            List<com.mhtextractor.uiport.OutputUnitVm> units, Map<String, PerFileOverrides> overrides,
            boolean imageMode, Supplier<Boolean> recursionCallback) {
        return new ExtractionRequest(sessionOutputFolder, units.stream().map(u ->
                new OutputUnitPlanner.OutputUnit(u.outputName(), u.group(), u.params(), u.paths(), u.outputPath()))
                .toList(), overrides, imageMode, recursionCallback);
    }

    /**
     * 单元执行器：一次输出单元提取的<b>接缝</b>。生产实现见 {@link #dispatch(PreviewCacheLifecycle)}；
     * 测试可注入桩，从而在不真跑 MHT 解析的前提下驱动统计累计 / 取消 / 失败继续等编排逻辑。
     */
    @FunctionalInterface
    public interface UnitProcessor {
        /**
         * @param unit              输出单元（顺序、单元内文件顺序均由调用方保证）
         * @param sessionOutputFolder 本次会话输出目录（图片单独合并模式用）
         * @param overrides         逐文件参数覆盖（文本 processor 用）
         * @param cancelSupplier    取消信号（透传给 processor）
         * @param recursionCallback 递归深度超限继续回调（后台线程同步等待其返回值）
         * @param callback          单元内进度回调（由本类映射为跨单元总进度）
         */
        BatchProcessor.ProcessStats process(OutputUnitPlanner.OutputUnit unit,
                                            String sessionOutputFolder,
                                            Map<String, PerFileOverrides> overrides,
                                            Supplier<Boolean> cancelSupplier,
                                            Supplier<Boolean> recursionCallback,
                                            BatchProcessor.ProgressCallback callback);
    }

    /** 跨单元总进度接收端（GUI 侧适配为 {@code Task.updateProgress(overall, 1.0)}）。 */
    @FunctionalInterface
    public interface ProgressSink {
        void update(double overallProgress);
    }

    /**
     * 一次提取的<b>不可变请求快照</b>（指南第 1 节第 1 条：不得把 {@code ObservableList} / 控件 /
     * 可继续变化的 {@link AppConfig} 引用交给后台任务）。
     *
     * <p>{@code units} 与 {@code overrides} 在构造时<b>防御性拷贝</b>，此后外部改动原集合不再影响本次提取。
     * 单元自身（{@link OutputUnitPlanner.OutputUnit}）在计划阶段已冻结：文件列表与输出路径都是 final，
     * 参数对象也已补齐运行时字段。</p>
     *
     * @param sessionOutputFolder 本次会话的输出目录（时间戳子目录，FX 线程上先建好）
     * @param units               输出单元快照（<b>执行顺序即列表顺序</b>）
     * @param overrides           逐文件参数覆盖（不可变视图）
     * @param imageMode           本次提取模式；仅作请求元信息记录，
     *                            <b>实际分派依据是单元自己的 {@code params.isImageModeEnabled()}</b>
     *                            （与搬迁前的 {@code processUnit} 完全一致：计划阶段已按该模式写回参数）
     * @param recursionCallback   递归深度超限确认回调（GUI 注入：FX 线程弹卡 + 本线程等待结果）
     */
    public record ExtractionRequest(String sessionOutputFolder,
                                    List<OutputUnitPlanner.OutputUnit> units,
                                    Map<String, PerFileOverrides> overrides,
                                    boolean imageMode,
                                    Supplier<Boolean> recursionCallback) {

        public ExtractionRequest {
            units = List.copyOf(units);
            overrides = Map.copyOf(overrides);
        }
    }

    /**
     * 一次提取的结果。
     *
     * @param stats 统计（取消路径下即"已完成单元"的 partial 统计）
     */
    public record ExtractionResult(BatchProcessor.ProcessStats stats) {
    }

    /**
     * 统计搬运（原 {@code app.ExtractionStats.from}，P3-B6 随记录迁入 {@code model} 后留在 app 层的
     * 唯一工厂，逐字照搬）：从批量处理器统计 1:1 搬运到中性 DTO（摘要行在<b>此刻</b>按当前 locale 求值，
     * 与原调用点时机一致；files/warnings 均拷贝，顺序不变）。
     *
     * @param stats 批量处理统计
     * @return 不可变快照（{@link com.mhtextractor.model.ExtractionStats}）
     */
    public static com.mhtextractor.model.ExtractionStats statsFrom(BatchProcessor.ProcessStats stats) {
        java.util.List<com.mhtextractor.model.ExtractionStats.FileOutcome> files = stats.getFileResults().stream()
                .map(r -> new com.mhtextractor.model.ExtractionStats.FileOutcome(
                        r.path(), r.outcome(), r.message(), java.util.List.copyOf(r.warnings())))
                .toList();
        String summary = stats.getSummaryLine();
        if (!stats.getWarnDetails().isEmpty()) summary += "\n" + String.join("\n", stats.getWarnDetails());
        return new com.mhtextractor.model.ExtractionStats(summary, stats.getFailCount(),
                stats.getSkipCount(), stats.getWarnCount(), files);
    }

    private final UnitProcessor unitProcessor;

    /**
     * 生产构造：文本/图片分派走 {@link #dispatch(PreviewCacheLifecycle)}。
     *
     * @param previewCacheLifecycle 预览缓存生命周期（图片提取复用缓存：命中即跳过解析与提取，并触发规则 (b)）
     */
    public WorkspaceExtractionService(PreviewCacheLifecycle previewCacheLifecycle) {
        this(dispatch(previewCacheLifecycle));
    }

    /**
     * 接缝构造：注入自定义单元执行器（测试用；生产请用
     * {@link #WorkspaceExtractionService(PreviewCacheLifecycle)}）。
     */
    WorkspaceExtractionService(UnitProcessor unitProcessor) {
        this.unitProcessor = unitProcessor;
    }

    /**
     * 执行一次提取。
     *
     * <p>行为要点（与搬迁前 {@code MainController} 内 {@code Task.call()} 逐字对应）：</p>
     * <ol>
     *   <li>单元顺序 = 请求列表顺序；单元内文件顺序 = {@code unit.getPaths()} 顺序；</li>
     *   <li>{@code cancelled.getAsBoolean()} 为真 → 打 {@code log.maincontroller.34}（实参 = 剩余单元数）
     *       并 <b>break</b>，已完成单元的结果保留在返回的 stats 里（partial）；</li>
     *   <li>单元抛异常 → 打 {@code log.maincontroller.36}、按 {@code fileCount()} 计失败、
     *       追加一条 {@code extract.unitFailed} 详情，然后<b>继续下一个单元</b>；</li>
     *   <li>跨单元进度 = {@link UnitProgressAggregator#overall(int, int, double)}，只增不减。</li>
     * </ol>
     *
     * @param request      不可变请求快照
     * @param cancelled    取消信号（GUI 侧即 {@code Task::isCancelled}）
     * @param progressSink 跨单元总进度接收端（0.0~1.0）；GUI 侧即 {@code Task.updateProgress}
     * @return 提取结果（含 partial 统计）
     */
    public ExtractionResult run(ExtractionRequest request,
                                Supplier<Boolean> cancelled,
                                ProgressSink progressSink) {
        List<OutputUnitPlanner.OutputUnit> units = request.units();
        Map<String, PerFileOverrides> overrides = request.overrides();
        Supplier<Boolean> recursionCallback = request.recursionCallback();
        try {
            UnitProgressAggregator progress = new UnitProgressAggregator(
                    units.stream().map(OutputUnitPlanner.OutputUnit::fileCount).toList());
            BatchProcessor.ProcessStats total = new BatchProcessor.ProcessStats();
            total.setStartTime(System.currentTimeMillis());
            total.setTotalFiles(progress.totalFiles());

            for (int i = 0; i < units.size(); i++) {
                if (cancelled.get()) {
                    log.info(I18n.msg("log.maincontroller.34", units.size() - i));
                    break;
                }
                OutputUnitPlanner.OutputUnit unit = units.get(i);
                log.info(I18n.msg("log.maincontroller.35", unit.label(), unit.fileCount(), unit.getOutputPath()));
                final int unitIndex = i;
                BatchProcessor.ProgressCallback progressCallback =
                        (current, _, _, subProgress) ->
                                progressSink.update(progress.overall(unitIndex, current, subProgress));
                try {
                    BatchProcessor.ProcessStats unitStats = unitProcessor.process(unit,
                            request.sessionOutputFolder(), overrides, cancelled, recursionCallback, progressCallback);
                    total.setSuccessCount(total.getSuccessCount() + unitStats.getSuccessCount());
                    total.setFailCount(total.getFailCount() + unitStats.getFailCount());
                    total.setSkipCount(total.getSkipCount() + unitStats.getSkipCount());
                    total.setWarnCount(total.getWarnCount() + unitStats.getWarnCount());
                    total.getFailDetails().addAll(unitStats.getFailDetails());
                    total.getSkipDetails().addAll(unitStats.getSkipDetails());
                    total.getWarnDetails().addAll(unitStats.getWarnDetails());
                    total.addAllFileResults(unitStats.getFileResults());
                } catch (Exception e) {
                    log.error(I18n.msg("log.maincontroller.36", unit.label()), e);
                    for (int k = 0; k < unit.fileCount(); k++) {
                        total.incrementFail();
                    }
                    total.addFailDetail(I18n.get("extract.unitFailed",
                            "unit", unit.label(), "reason", e.getMessage()));
                }
            }
            total.setEndTime(System.currentTimeMillis());
            log.info("{}", total);
            return new ExtractionResult(total);
        } catch (Exception e) {
            log.error(I18n.msg("log.maincontroller.37"), e);
            throw new RuntimeException(e);
        }
    }

    /**
     * 生产单元执行器：文本/图片分派。
     *
     * <p>与搬迁前 {@code MainController.processUnit} 逐字对应：图片模式注入
     * {@code previewCacheLifecycle}（缓存命中即跳过解析与提取）+ 单独输出模式经显式输出名指定组名 / 来源名；
     * 文本单独模式先建目录（失败打 {@code log.maincontroller.40}）再 {@code processSeparate}。</p>
     *
     * @param previewCacheLifecycle 预览缓存生命周期
     */
    static UnitProcessor dispatch(PreviewCacheLifecycle previewCacheLifecycle) {
        return (unit, sessionOutputFolder, overrides, cancelSupplier, recursionCallback, callback) -> {
            AppConfig config = unit.getParams();
            List<BatchProcessor.MhtFileInfo> files = BatchProcessor.buildMhtFileInfoList(unit.getPaths());
            if (config.isImageModeEnabled()) {
                // 会话 10：注入预览缓存生命周期 → 提取复用（命中跳过解析与提取）+ 规则 (b) 完成删除
                ImageBatchProcessor processor = new ImageBatchProcessor(config, previewCacheLifecycle);
                processor.setCancelSupplier(cancelSupplier);
                processor.setRecursionContinueCallback(recursionCallback);
                if (config.isSingleOutputMode()) {
                    // 逐文件覆盖项透传：合并目录名优先取第一个文件的用户编辑标题
                    return processor.process(files, sessionOutputFolder, unit.getOutputName(), callback, overrides);
                }
                // 单独模式没有显式目录名（传 null），但仍需逐文件覆盖项用于图片标题命名
                return processor.process(files, unit.getOutputPath(), null, callback, overrides);
            } else {
                TextBatchProcessor processor = new TextBatchProcessor(config);
                processor.setCancelSupplier(cancelSupplier);
                processor.setRecursionContinueCallback(recursionCallback);
                if (config.isSeparateFiles()) {
                    File outDir = new File(unit.getOutputPath());
                    if (!outDir.exists() && !outDir.mkdirs()) {
                        log.warn(I18n.msg("log.maincontroller.40", unit.getOutputPath()));
                    }
                    return processor.processSeparate(files, unit.getOutputPath(), callback, overrides);
                }
                return processor.processMerged(files, unit.getOutputPath(), callback, overrides);
            }
        };
    }
}
package com.mhtextractor.processor;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.i18n.I18n;
import com.mhtextractor.output.Archiver;
import com.mhtextractor.util.FileUtils;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.nio.file.Paths;
import java.util.function.DoubleConsumer;

/**
 * ZIP/CBZ 归档 + 源目录清理（Q12 从 {@code ImageBatchProcessor.archiveWithCleanup} 原样移出）。
 *
 * <p><b>为什么两个输出策略共用它、而不是各写一份</b>：归档动作本身（{@link Archiver}）与"失败则
 * <b>不删源目录</b>"这条纪律是同一份实现（P0-2 的修复点）。两者真正不同的只是<b>失败之后谁记结果</b>
 * 与<b>进度怎么报</b>——那是各自策略的事，通过 {@code progress} 回调传入。</p>
 *
 * <p>进度参数只在"逐文件归档"（单独输出）时有意义：那时传 {@code fileProgress != null}；
 * 合并输出的批级归档传 {@code null}，于是只打 debug 日志（与旧实现同形）。</p>
 */
@Slf4j
final class OutputArchive {

    private OutputArchive() {
    }

    /**
     * 归档 + 清理源目录。
     *
     * @param zipBase   ZIP 进度基准（仅在 {@code fileProgress != null} 时使用）
     * @param zipRange  ZIP 进度区间
     * @param cbzRange  CBZ 进度区间
     * @param zipDone   归档过程中的进度接收者（0.0~1.0 → 调用方自行映射到文件子进度）；
     *                  为 {@code null} 表示"批级归档"（只打 debug）
     * @return true = 归档成功（源目录已被删除）或本来就无需归档；false = 归档失败（源目录保留）
     */
    static boolean archiveWithCleanup(AppConfig config, String sourceDir, String outputFolder,
                                      String baseName, double zipBase, double zipRange,
                                      double cbzRange, DoubleConsumer zipDone) {
        if (!config.isEnableZipPackaging() && !config.isEnableCbzPackaging()) {
            return true;
        }
        File dir = new File(sourceDir);
        File[] children = dir.listFiles();
        int childCount = children == null ? 0 : children.length;
        if (childCount == 0) {
            FileUtils.deleteDirectory(dir);
            log.info(I18n.msg("log.imagebatchprocessor.50", sourceDir));
            return true;
        }
        boolean zipOk = true;
        boolean cbzOk = true;
        if (config.isEnableZipPackaging()) {
            zipOk = Archiver.createZip(sourceDir,
                    Paths.get(outputFolder, baseName + ".zip").toString(), count -> {
                        double ratio = (double) count / childCount;
                        if (zipDone != null) {
                            zipDone.accept(zipBase + zipRange * ratio);
                        } else {
                            log.debug(I18n.msg("log.imagebatchprocessor.51", count, childCount));
                        }
                    });
        }
        if (config.isEnableCbzPackaging()) {
            cbzOk = Archiver.createCbz(sourceDir,
                    Paths.get(outputFolder, baseName + ".cbz").toString(), count -> {
                        double ratio = (double) count / childCount;
                        if (zipDone != null) {
                            zipDone.accept(zipBase + zipRange + cbzRange * ratio);
                        } else {
                            log.debug(I18n.msg("log.imagebatchprocessor.52", count, childCount));
                        }
                    });
        }
        if (!zipOk || !cbzOk) {
            log.error(I18n.msg("log.imagebatchprocessor.53", zipOk, cbzOk, sourceDir));
            return false;
        }
        FileUtils.deleteDirectory(dir);
        log.info(I18n.msg("log.imagebatchprocessor.54", sourceDir));
        return true;
    }
}
