    /** AppConfig -> 原始控件值；null 字符串变为空串，顺序沿用旧 load。 */
    public static Map<String, Object> values(AppConfig config, ParamSchemaVm schema) {
        Map<String, Object> result = new LinkedHashMap<>();
        for (Binding b : BINDINGS) {
            if (schema.fields().stream().noneMatch(f -> f.id().equals(b.id()))) continue;
            Object value = b.read().apply(config);
            result.put(b.id(), value == null ? "" : value);
        }
        return result;
    }

    /** 一个开关的联动：返回需要禁用并复位的字段值；启用时保留原输入。 */
    public static Map<String, Object> disabledValues(ParamSchemaVm schema, Map<String, Object> values,
                                                      String controller) {
        Map<String, Object> result = new LinkedHashMap<>();
        for (Field f : schema.fields()) {
            if (controller.equals(f.enabledBy()) && !Boolean.TRUE.equals(values.get(controller)))
                result.put(f.id(), f.disabledValue());
        }
        return result;
    }

    /** 两页控件值 -> 参数快照；仅关闭的图片区域标记收为 null，其余逐值保留。 */
    public static AppConfig collect(Map<String, Object> values) {
        AppConfig config = new AppConfig();
        for (Binding b : BINDINGS) {
            Object value = values.get(b.id());
            Field f = java.util.stream.Stream.concat(TEXT.fields().stream(), IMAGE.fields().stream())
                    .filter(field -> field.id().equals(b.id())).findFirst().orElseThrow();
            if (f.nullWhenDisabled() && !Boolean.TRUE.equals(values.get(f.enabledBy()))) value = null;
            b.write().accept(config, value);
        }
        return config;
    }
}
// P4-10: read-only C temp inventory; evidence is written only to H:/TEST/mht.
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
import { under, utf8 } from './path-assertions.mjs';

const roots = [(process.env.LOCALAPPDATA || '') + '/Temp', 'C:/Windows/Temp'];
const projectRoot = roots[0];

export function snapshot() {
  const entries = [], errors = [];
  function walk(dir) {
    let children;
    try { children = fs.readdirSync(dir, { withFileTypes: true }); }
    catch (error) { errors.push({ path: dir, code: error.code }); return; }
    for (const child of children) {
      const full = dir + '/' + child.name;
      try {
        const stat = fs.lstatSync(full);
        entries.push({ path: full, directory: child.isDirectory(), bytes: stat.size,
          createdMs: stat.birthtimeMs, modifiedMs: stat.mtimeMs });
        // Inventory other applications at the temp root; recurse only into project artifacts.
        // DSH snapshots can contain a whole workspace and are outside the product assertion.
        if (child.isDirectory() && category(full) === 'project') {
          if (child.isSymbolicLink()) errors.push({ path: full, code: 'PROJECT_LINK_NOT_FOLLOWED' });
          else walk(full);
        }
      } catch (error) { errors.push({ path: full, code: error.code }); }
    }
  }
  for (const root of roots) walk(root);
  entries.sort((a, b) => a.path.localeCompare(b.path));
  return { capturedAt: new Date().toISOString(), roots, entries, errors,
    inventoryScope: 'Temp root entries in both roots; recurse only into mht-extractor-* project artifacts' };
}

export function category(file) {
  const normal = file.replaceAll('\\', '/').toLowerCase();
  for (const root of roots) {
    const prefix = root.toLowerCase() + '/';
    if (!normal.startsWith(prefix)) continue;
    const name = normal.slice(prefix.length).split('/')[0];
    if (root === projectRoot && name.startsWith('mht-extractor-')) return 'project';
    if (name.startsWith('dsh-workspace-changes-')) return 'dshSnapshots';
    if (name.startsWith('dd_backgrounddownload_')) return 'visualStudio';
  }
  return 'other';
}

export function compare(before, after) {
  const old = new Map(before.entries.map(entry => [entry.path, entry]));
  const added = [], modified = [];
  const counts = { project: 0, dshSnapshots: 0, visualStudio: 0, other: 0 };
  const modifiedCounts = { ...counts };
  for (const entry of after.entries) {
    const prior = old.get(entry.path);
    if (!prior) { added.push(entry); counts[category(entry.path)]++; }
    else if (entry.createdMs !== prior.createdMs || entry.modifiedMs !== prior.modifiedMs || entry.bytes !== prior.bytes) {
      modified.push(entry); modifiedCounts[category(entry.path)]++;
    }
  }
  const unreadable = [...before.errors, ...after.errors];
  // Errors in other applications' subdirectories do not hide the project root names.
  // A failure to enumerate Temp itself or any existing mht-extractor-* subtree does.
  const projectUnreadable = unreadable.filter(error =>
    error.path.replaceAll('\\', '/').toLowerCase() === projectRoot.toLowerCase() || category(error.path) === 'project');
  return { before: before.capturedAt, after: after.capturedAt, counts, modifiedCounts, added, modified,
    unreadable, projectUnreadable,
    projectStatus: counts.project ? 'FAIL' : projectUnreadable.length ? 'UNVERIFIED' : 'PASS',
    scope: '%LOCALAPPDATA%/Temp/mht-extractor-* and descendants',
    classificationScope: after.inventoryScope,
    unverified: ['Entire C drive', 'Files created and deleted between snapshots',
      ...(unreadable.length ? ['Unreadable entries listed in unreadable'] : [])] };
}

function controls() {
  const baseline = { capturedAt: 'before', entries: [], errors: [] };
  const project = { path: projectRoot + '/mht-extractor-preview/new.txt', bytes: 1, createdMs: 1, modifiedMs: 1 };
  const unrelated = [
    { ...project, path: projectRoot + '/dsh-workspace-changes-control/new.json' },
    { ...project, path: projectRoot + '/dd_BackgroundDownload_control.log' }
  ];
  const red = compare(baseline, { ...baseline, entries: [project, ...unrelated] });
  assert.equal(red.projectStatus, 'FAIL');
  assert.deepEqual(red.counts, { project: 1, dshSnapshots: 1, visualStudio: 1, other: 0 });
  const green = compare(baseline, { ...baseline, entries: unrelated });
  assert.equal(green.projectStatus, 'PASS');
  assert.equal(compare(baseline, { ...baseline, errors: [{ path: projectRoot, code: 'EACCES' }] }).projectStatus, 'UNVERIFIED');
  console.log('C-AUDIT SNAPSHOT CONTROL: project violation=FAIL unrelated additions=PASS unreadable root=UNVERIFIED');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const argv = process.argv.slice(2);
  if (argv.includes('--controls')) controls();
  else if (argv.includes('--print')) console.log(JSON.stringify(snapshot()));
  else {
    const index = argv.indexOf('--root');
    assert.ok(index >= 0 && argv[index + 1], 'Supply --root H:/TEST/mht/p4-10-...');
    const root = path.resolve(argv[index + 1]);
    under(root, 'H:/TEST/mht');
    assert.ok(path.basename(root).startsWith('p4-10-'), 'P4-10 evidence root required');
    assert.ok(argv.includes('--before') !== argv.includes('--after'), 'Choose exactly one of --before or --after');
    fs.mkdirSync(root, { recursive: true });
    const phase = argv.includes('--before') ? 'before' : 'after';
    const file = path.join(root, 'c-' + phase + '.json');
    assert.ok(!fs.existsSync(file), 'Use fresh evidence; refuse to overwrite ' + file);
    const current = snapshot();
    fs.writeFileSync(file, JSON.stringify(current, null, 2));
    if (phase === 'before') console.log(`C-AUDIT BEFORE: entries=${current.entries.length} unreadable=${current.errors.length}`);
    else {
      const result = compare(JSON.parse(utf8(path.join(root, 'c-before.json'))), current);
      fs.writeFileSync(path.join(root, 'c-audit.json'), JSON.stringify(result, null, 2));
      console.log('C-AUDIT: ' + JSON.stringify(result));
      process.exitCode = result.projectStatus === 'PASS' ? 0 : result.projectStatus === 'FAIL' ? 1 : 2;
    }
  }
}
package com.mhtextractor.backend;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.uiport.OutputUnitVm;
import com.mhtextractor.uiport.ParamSchemaVm;

import java.io.IOException;
import java.util.List;

/** Explicit wire dictionaries; schema records need no native reflection registration. */
final class IpcParamCodec {
    private final ObjectMapper json;

    IpcParamCodec(ObjectMapper json) { this.json = json; }

    AppConfig readConfig(JsonNode value) throws IOException {
        if (!value.isObject()) throw new IllegalArgumentException("Config object required");
        var defaults = config(new AppConfig());
        var fields = value.fields();
        while (fields.hasNext()) {
            var field = fields.next();
            var expected = defaults.get(field.getKey());
            if (expected == null || (expected.isBoolean() ? !field.getValue().isBoolean()
                    : !field.getValue().isTextual() && !field.getValue().isNull())) {
                throw new IllegalArgumentException("Invalid Config field: " + field.getKey());
            }
        }
        return json.treeToValue(value, AppConfig.class);
    }

    @SuppressWarnings("deprecation")
    ObjectNode config(AppConfig c) {
        return json.createObjectNode()
                .put("separateFiles", c.isSeparateFiles())
                .put("enableLimit", c.isEnableContentLimit()).put("startMarker", c.getStartMarker())
                .put("endMarker", c.getEndMarker()).put("useRegex", c.isUseRegex())
                .put("enableCustomTemplate", c.isEnableTemplate()).put("startTemplate", c.getStartTemplate())
                .put("endTemplate", c.getEndTemplate()).put("addChapterNumber", c.isAddChapterNumber())
                .put("autoFixEncoding", c.isAutoFixEncoding()).put("enableTitleExtract", c.isEnableTitleExtraction())
                .put("titleStartMarker", c.getTitleStartMarker()).put("titleEndMarker", c.getTitleEndMarker())
                .put("titleUseRegex", c.isTitleUseRegex()).put("imageNameExtractEnabled", c.isEnableNameExtraction())
                .put("imageNameStartMarker", c.getImageNameStartMarker()).put("imageNameEndMarker", c.getImageNameEndMarker())
                .put("imageRegionExtractEnabled", c.isEnableRegionExtraction())
                .put("imageRegionStartMarker", c.getImageRegionStartMarker()).put("imageRegionEndMarker", c.getImageRegionEndMarker())
                .put("imageRenameEnabled", c.isEnableBatchRenaming()).put("imageZipEnabled", c.isEnableZipPackaging())
                .put("imageCbzEnabled", c.isEnableCbzPackaging()).put("singleOutputMode", c.isSingleOutputMode())
                .put("legacyMemoryMode", c.isHighSpeedMemoryMode()).put("nameLimitStart", c.getNameLimitStart())
                .put("nameLimitEnd", c.getNameLimitEnd()).put("contentLimitStart", c.getContentLimitStart())
                .put("contentLimitEnd", c.getContentLimitEnd());
    }

    ObjectNode runtimeConfig(AppConfig c) {
        return config(c).put("inputFolder", c.getInputFolder()).put("outputFolder", c.getOutputFolder())
                .put("imageModeEnabled", c.isImageModeEnabled()).put("openFolderAfterComplete", c.isOpenFolderAfterComplete());
    }

    ArrayNode units(List<OutputUnitVm> units) {
        var result = json.createArrayNode();
        for (var unit : units) {
            var node = result.addObject().put("outputName", unit.outputName()).put("group", unit.group())
                    .put("outputPath", unit.outputPath()).put("labelKey", unit.labelKey());
            node.set("params", runtimeConfig(unit.params()));
            var paths = node.putArray("paths");
            unit.paths().forEach(paths::add);
        }
        return result;
    }

    ObjectNode schema(ParamSchemaVm schema) {
        var result = json.createObjectNode().put("imageMode", schema.imageMode());
        var groups = result.putArray("groups");
        for (var group : schema.groups()) groups.addObject().put("id", group.id())
                .put("labelKey", group.labelKey()).put("noteKey", group.noteKey());
        var fields = result.putArray("fields");
        for (var field : schema.fields()) {
            var node = fields.addObject().put("id", field.id()).put("type", field.type().name())
                    .put("labelKey", field.labelKey()).put("group", field.group())
                    .put("enabledBy", field.enabledBy()).put("nullWhenDisabled", field.nullWhenDisabled())
                    .put("promptText", field.promptText()).put("templateEnter", field.templateEnter());
            scalar(node, "defaultValue", field.defaultValue());
            scalar(node, "disabledValue", field.disabledValue());
        }
        return result;
    }

    private void scalar(ObjectNode node, String key, Object value) {
        switch (value) {
            case null -> node.putNull(key);
            case Boolean b -> node.put(key, b);
            case String s -> node.put(key, s);
            default -> throw new IllegalStateException("Unsupported schema value: " + key);
        }
    }
}

package com.mhtextractor.app;

import com.mhtextractor.cache.PreviewCacheLifecycle;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.i18n.I18n;
import com.mhtextractor.processor.BatchProcessor;
import com.mhtextractor.processor.ImageBatchProcessor;
import com.mhtextractor.processor.PerFileOverrides;
import com.mhtextractor.processor.TextBatchProcessor;
import com.mhtextractor.util.OutputUnitPlanner;
import com.mhtextractor.util.UnitProgressAggregator;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

/**
 * 工作区提取服务（Q3 / P2）—— 把「点开始提取之后、结果回到界面之前」的<b>业务段</b>从 GUI 控制器
 * 搬进无头应用层。
 *
 * <p><b>搬进来的是什么</b>：逐输出单元调用 processor、跨单元进度聚合、统计累计（成功/失败/跳过/警告
 * + 三条详情 + 结构化单文件结果）、取消传播（{@code cancelled} 为真即跳出，已完成单元结果保留为
 * partial）、单元失败不中断整批、以及文本/图片的分派（{@link UnitProcessor}）。</p>
 *
 * <p><b>有意不搬的是什么</b>（属渲染层 / 宿主生命周期，留在
 * {@code com.mhtextractor.gui.controller.ExtractionTaskCoordinator}）：</p>
 * <ul>
 *   <li>JavaFX {@code Task} 的创建/启动/取消与 {@code progressProperty} 映射；</li>
 *   <li><b>递归深度超限确认卡</b>：{@code Platform.runLater} + {@code NotificationHost} 只能跑在 FX 线程，
 *       本类只接收一个 {@link Supplier}（{@link ExtractionRequest#recursionCallback()}）并在后台线程同步等待
 *       其返回值 —— 决策机制仍由 GUI 注入，等待语义与搬迁前一致；</li>
 *   <li>提取完成后打开输出目录、满格条三态配色、结果回写列表条目。</li>
 * </ul>
 *
 * <p><b>日志与 i18n 边界</b>：本类<b>只</b>用 {@code log.*} 键（业务层日志已国际化，随
 * {@code log.maincontroller.*} 逐键保持不变），<b>不新增</b>任何 {@code I18n.get} 界面文案，因此
 * {@code ArchitectureTest.businessLayerI18nUsageDoesNotGrow} 的基线（52）不受影响。
 * 唯一的 {@code I18n.get} 是单元失败详情键 {@code extract.unitFailed} —— 它在搬迁前就由提取业务段产出，
 * 是"写入统计详情的业务文案"而非界面文案，原样保留。</p>
 *
 * <p><b>本类零 JavaFX</b>，由 {@code ArchitectureTest.businessPackagesHaveNoUiFrameworkDependency}
 * 按字节码常量池强制。</p>
 */
@Slf4j
public final class WorkspaceExtractionService {

    /** 端口快照转为既有执行请求；不重新规划，确保执行的就是前端查询所得的计划。 */
    public static ExtractionRequest fromPlan(String sessionOutputFolder,
            List<com.mhtextractor.uiport.OutputUnitVm> units, Map<String, PerFileOverrides> overrides,
            boolean imageMode, Supplier<Boolean> recursionCallback) {
        return new ExtractionRequest(sessionOutputFolder, units.stream().map(u ->
                new OutputUnitPlanner.OutputUnit(u.outputName(), u.group(), u.params(), u.paths(), u.outputPath()))
                .toList(), overrides, imageMode, recursionCallback);
    }

    /**
     * 单元执行器：一次输出单元提取的<b>接缝</b>。生产实现见 {@link #dispatch(PreviewCacheLifecycle)}；
     * 测试可注入桩，从而在不真跑 MHT 解析的前提下驱动统计累计 / 取消 / 失败继续等编排逻辑。
     */
    @FunctionalInterface
    public interface UnitProcessor {
        /**
         * @param unit              输出单元（顺序、单元内文件顺序均由调用方保证）
         * @param sessionOutputFolder 本次会话输出目录（图片单独合并模式用）
         * @param overrides         逐文件参数覆盖（文本 processor 用）
         * @param cancelSupplier    取消信号（透传给 processor）
         * @param recursionCallback 递归深度超限继续回调（后台线程同步等待其返回值）
         * @param callback          单元内进度回调（由本类映射为跨单元总进度）
         */
        BatchProcessor.ProcessStats process(OutputUnitPlanner.OutputUnit unit,
                                            String sessionOutputFolder,
                                            Map<String, PerFileOverrides> overrides,
                                            Supplier<Boolean> cancelSupplier,
                                            Supplier<Boolean> recursionCallback,
                                            BatchProcessor.ProgressCallback callback);
    }

    /** 跨单元总进度接收端（GUI 侧适配为 {@code Task.updateProgress(overall, 1.0)}）。 */
    @FunctionalInterface
    public interface ProgressSink {
        void update(double overallProgress);
    }

    /**
     * 一次提取的<b>不可变请求快照</b>（指南第 1 节第 1 条：不得把 {@code ObservableList} / 控件 /
     * 可继续变化的 {@link AppConfig} 引用交给后台任务）。
     *
     * <p>{@code units} 与 {@code overrides} 在构造时<b>防御性拷贝</b>，此后外部改动原集合不再影响本次提取。
     * 单元自身（{@link OutputUnitPlanner.OutputUnit}）在计划阶段已冻结：文件列表与输出路径都是 final，
     * 参数对象也已补齐运行时字段。</p>
     *
     * @param sessionOutputFolder 本次会话的输出目录（时间戳子目录，FX 线程上先建好）
     * @param units               输出单元快照（<b>执行顺序即列表顺序</b>）
     * @param overrides           逐文件参数覆盖（不可变视图）
     * @param imageMode           本次提取模式；仅作请求元信息记录，
     *                            <b>实际分派依据是单元自己的 {@code params.isImageModeEnabled()}</b>
     *                            （与搬迁前的 {@code processUnit} 完全一致：计划阶段已按该模式写回参数）
     * @param recursionCallback   递归深度超限确认回调（GUI 注入：FX 线程弹卡 + 本线程等待结果）
     */
    public record ExtractionRequest(String sessionOutputFolder,
                                    List<OutputUnitPlanner.OutputUnit> units,
                                    Map<String, PerFileOverrides> overrides,
                                    boolean imageMode,
                                    Supplier<Boolean> recursionCallback) {

        public ExtractionRequest {
            units = List.copyOf(units);
            overrides = Map.copyOf(overrides);
        }
    }

    /**
     * 一次提取的结果。
     *
     * @param stats 统计（取消路径下即"已完成单元"的 partial 统计）
     */
    public record ExtractionResult(BatchProcessor.ProcessStats stats) {
    }

    /**
     * 统计搬运（原 {@code app.ExtractionStats.from}，P3-B6 随记录迁入 {@code model} 后留在 app 层的
     * 唯一工厂，逐字照搬）：从批量处理器统计 1:1 搬运到中性 DTO（摘要行在<b>此刻</b>按当前 locale 求值，
     * 与原调用点时机一致；files/warnings 均拷贝，顺序不变）。
     *
     * @param stats 批量处理统计
     * @return 不可变快照（{@link com.mhtextractor.model.ExtractionStats}）
     */
    public static com.mhtextractor.model.ExtractionStats statsFrom(BatchProcessor.ProcessStats stats) {
        java.util.List<com.mhtextractor.model.ExtractionStats.FileOutcome> files = stats.getFileResults().stream()
                .map(r -> new com.mhtextractor.model.ExtractionStats.FileOutcome(
                        r.path(), r.outcome(), r.message(), java.util.List.copyOf(r.warnings())))
                .toList();
        String summary = stats.getSummaryLine();
        if (!stats.getWarnDetails().isEmpty()) summary += "\n" + String.join("\n", stats.getWarnDetails());
        return new com.mhtextractor.model.ExtractionStats(summary, stats.getFailCount(),
                stats.getSkipCount(), stats.getWarnCount(), files);
    }

    private final UnitProcessor unitProcessor;

    /**
     * 生产构造：文本/图片分派走 {@link #dispatch(PreviewCacheLifecycle)}。
     *
     * @param previewCacheLifecycle 预览缓存生命周期（图片提取复用缓存：命中即跳过解析与提取，并触发规则 (b)）
     */
    public WorkspaceExtractionService(PreviewCacheLifecycle previewCacheLifecycle) {
        this(dispatch(previewCacheLifecycle));
    }

    /**
     * 接缝构造：注入自定义单元执行器（测试用；生产请用
     * {@link #WorkspaceExtractionService(PreviewCacheLifecycle)}）。
     */
    WorkspaceExtractionService(UnitProcessor unitProcessor) {
        this.unitProcessor = unitProcessor;
    }

    /**
     * 执行一次提取。
     *
     * <p>行为要点（与搬迁前 {@code MainController} 内 {@code Task.call()} 逐字对应）：</p>
     * <ol>
     *   <li>单元顺序 = 请求列表顺序；单元内文件顺序 = {@code unit.getPaths()} 顺序；</li>
     *   <li>{@code cancelled.getAsBoolean()} 为真 → 打 {@code log.maincontroller.34}（实参 = 剩余单元数）
     *       并 <b>break</b>，已完成单元的结果保留在返回的 stats 里（partial）；</li>
     *   <li>单元抛异常 → 打 {@code log.maincontroller.36}、按 {@code fileCount()} 计失败、
     *       追加一条 {@code extract.unitFailed} 详情，然后<b>继续下一个单元</b>；</li>
     *   <li>跨单元进度 = {@link UnitProgressAggregator#overall(int, int, double)}，只增不减。</li>
     * </ol>
     *
     * @param request      不可变请求快照
     * @param cancelled    取消信号（GUI 侧即 {@code Task::isCancelled}）
     * @param progressSink 跨单元总进度接收端（0.0~1.0）；GUI 侧即 {@code Task.updateProgress}
     * @return 提取结果（含 partial 统计）
     */
    public ExtractionResult run(ExtractionRequest request,
                                Supplier<Boolean> cancelled,
                                ProgressSink progressSink) {
        List<OutputUnitPlanner.OutputUnit> units = request.units();
        Map<String, PerFileOverrides> overrides = request.overrides();
        Supplier<Boolean> recursionCallback = request.recursionCallback();
        try {
            UnitProgressAggregator progress = new UnitProgressAggregator(
                    units.stream().map(OutputUnitPlanner.OutputUnit::fileCount).toList());
            BatchProcessor.ProcessStats total = new BatchProcessor.ProcessStats();
            total.setStartTime(System.currentTimeMillis());
            total.setTotalFiles(progress.totalFiles());

            for (int i = 0; i < units.size(); i++) {
                if (cancelled.get()) {
                    log.info(I18n.msg("log.maincontroller.34", units.size() - i));
                    break;
                }
                OutputUnitPlanner.OutputUnit unit = units.get(i);
                log.info(I18n.msg("log.maincontroller.35", unit.label(), unit.fileCount(), unit.getOutputPath()));
                final int unitIndex = i;
                BatchProcessor.ProgressCallback progressCallback =
                        (current, _, _, subProgress) ->
                                progressSink.update(progress.overall(unitIndex, current, subProgress));
                try {
                    BatchProcessor.ProcessStats unitStats = unitProcessor.process(unit,
                            request.sessionOutputFolder(), overrides, cancelled, recursionCallback, progressCallback);
                    total.setSuccessCount(total.getSuccessCount() + unitStats.getSuccessCount());
                    total.setFailCount(total.getFailCount() + unitStats.getFailCount());
                    total.setSkipCount(total.getSkipCount() + unitStats.getSkipCount());
                    total.setWarnCount(total.getWarnCount() + unitStats.getWarnCount());
                    total.getFailDetails().addAll(unitStats.getFailDetails());
                    total.getSkipDetails().addAll(unitStats.getSkipDetails());
                    total.getWarnDetails().addAll(unitStats.getWarnDetails());
                    total.addAllFileResults(unitStats.getFileResults());
                } catch (Exception e) {
                    log.error(I18n.msg("log.maincontroller.36", unit.label()), e);
                    for (int k = 0; k < unit.fileCount(); k++) {
                        total.incrementFail();
                    }
                    total.addFailDetail(I18n.get("extract.unitFailed",
                            "unit", unit.label(), "reason", e.getMessage()));
                }
    public List<OutputUnitVm> outputUnitPlan(boolean checkedOnly) {
        return plan(context.dataOrder(), context.imageMode(), context.textParamsCache(), context.imageParamsCache(),
                sessionOutputFolder == null ? context.outputFolder() : sessionOutputFolder,
                context.inputFolder(), context.outputFolder(), context.openFolderAfterComplete(), checkedOnly)
                .stream().map(u -> new OutputUnitVm(u.getOutputName(), u.isGroup(), u.getParams(),
