    }

    /** 图片模式缓存（原 {@code imageParamsCache} 字段读）。 */
    public AppConfig image() {
        return image;
    }

    /** 按模式取缓存（{@code imageMode=true} → 图片，否则文本）。 */
    public AppConfig forMode(boolean imageMode) {
